"use client";

import { useState } from "react";
import Link from "next/link";
import {
  collection,
  getDocs,
  query,
  updateDoc,
  where,
  serverTimestamp,
} from "firebase/firestore";
import { RutaProtegida } from "@/components/RutaProtegida";
import { Encabezado } from "@/components/Encabezado";
import { db } from "@/lib/firebase/client";

const IMAGENES_POR_PATOLOGIA: Record<string, string[]> = {"Cráneo (frente, perfil, MNP, FNP, cavum, Towne, Hirtz)": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Tórax": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Parrilla costal": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Esternón": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Clavícula": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Abdomen": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Columna cervical – cuello": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Columna dorsal": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Columna lumbar": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Sacro y coxis": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Espinograma y miembros inferiores (MMII)": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Hombro": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Brazo (húmero)": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Codo": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Antebrazo": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Muñeca": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Mano": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Dedos": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Pulgar": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Pelvis": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Cadera": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Fémur": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Rodilla": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Pierna": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Tobillo": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Pie": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "Pie con carga": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"]};

function ImportarImagenesRX() {
  const [estado, setEstado] = useState<"inicial" | "cargando" | "listo" | "error">(
    "inicial"
  );
  const [log, setLog] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);

  async function aplicar() {
    setEstado("cargando");
    setError(null);
    const lineas: string[] = [];
    try {
      const q = query(collection(db, "protocolos"), where("modalidad", "==", "RX"));
      const snap = await getDocs(q);

      for (const d of snap.docs) {
        const patologia = (d.data().patologia as string) ?? "";
        const imagenes = IMAGENES_POR_PATOLOGIA[patologia];
        if (imagenes && imagenes.length > 0) {
          await updateDoc(d.ref, { imagenes, updatedAt: serverTimestamp() });
          lineas.push(`OK ${patologia} - ${imagenes.length} imagen(es)`);
        } else {
          lineas.push(`-- ${patologia} (sin imagenes para este estudio)`);
        }
        setLog([...lineas]);
      }
      setEstado("listo");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error desconocido");
      setEstado("error");
    }
  }

  return (
    <div className="flex h-screen flex-col bg-bg">
      <Encabezado />
      <main className="flex-1 overflow-y-auto px-6 py-6">
        <div className="mx-auto max-w-xl">
          <Link href="/admin" className="mb-4 inline-block text-xs text-ink-faint hover:text-ink">
            ← Volver
          </Link>
          <h1 className="mb-2 text-lg font-semibold text-ink">
            Aplicar imágenes a los protocolos de RX
          </h1>
          <p className="mb-6 text-sm text-ink-dim">
            Busca cada protocolo de RX existente por su nombre y le agrega las fotos de
            posicionamiento correspondientes, sacadas del documento de Intecnus. Se puede
            correr más de una vez sin problema (reemplaza las imágenes, no las duplica).
          </p>

          {estado === "inicial" && (
            <button
              onClick={aplicar}
              className="rounded bg-rm-dim px-4 py-2 text-sm font-medium text-ink hover:bg-rm hover:text-bg"
            >
              Aplicar imágenes
            </button>
          )}

          {estado === "cargando" && (
            <p className="mb-3 font-mono text-sm text-ink-faint">Procesando…</p>
          )}

          {log.length > 0 && (
            <div className="mt-4 max-h-96 overflow-y-auto rounded border border-border bg-surface p-3">
              {log.map((l, i) => (
                <p key={i} className="font-mono text-xs text-ink-dim">
                  {l}
                </p>
              ))}
            </div>
          )}

          {estado === "listo" && (
            <div className="mt-4 rounded border border-rx-dim bg-rx-dim/10 p-4">
              <p className="text-sm text-ink">
                Listo.{" "}
                <Link href="/protocolos" className="text-rm hover:underline">
                  Ir a Protocolos
                </Link>
              </p>
            </div>
          )}

          {estado === "error" && (
            <p className="mt-4 rounded border border-alert-dim bg-alert-dim/20 px-3 py-2 text-sm text-alert">
              {error}
            </p>
          )}
        </div>
      </main>
    </div>
  );
}

export default function ImportarImagenesRXPage() {
  return (
    <RutaProtegida rolRequerido="admin">
      <ImportarImagenesRX />
    </RutaProtegida>
  );
}
